        let cInputs = Inputs.vectors(H.Vector.self, seed: 0x8A8E_2F9F_15EC_4E99)
        let sentinel = Inputs.sentinel(H.Lane.self, count: 4 * H.laneCount)
        for (a, b, c) in mixedTriples(aInputs, bInputs, cInputs, seed: 0x3987_DF62_B4E8_DBF5) {
            let portLanes = unsafe withGuardedLanes(sentinel) { destination in
                unsafe portStoreInterleaved4F32ConstantD(a, b, c, to: destination)
            }.lanes
            let referenceLanes = unsafe withGuardedLanes(sentinel) { destination in
                unsafe highwayStoreInterleaved4F32ConstantD(a, b, c, to: destination)
            }.lanes
            mismatches.check(
                portLanes,
                referenceLanes,
                "a: \(describe(a)), b: \(describe(b)), c: \(describe(c))"
            )
        }
        mismatches.record()
    }

    @Test func repeatingBlock() {
        let mismatches = Mismatches("portRepeatingBlockF32")
        let vectorInputs = Inputs.vectors(H.Vector.self, seed: 0xDCFA_57CA_433F_3AE8)
        for vector in vectorInputs {
            mismatches.check(
                portRepeatingBlockF32(vector[0], vector[1], vector[2], vector[3]),
                highwayRepeatingBlockF32(vector[0], vector[1], vector[2], vector[3]),
                "lanes: \(describe(vector))"
            )
        }
        mismatches.record()
    }
}
